function chartFor(q) {
  if (/over time|trend|monthly|months|growth/i.test(q)) return 'line';
  if (/vs|compar|which|rank|leads?|highest|largest|top|most|best/i.test(q)) return 'sorted-bars';
  if (/mix|share|composition|breakdown/i.test(q)) return 'stacked-bars';
  if (/versus|relation|correlation|scatter/i.test(q)) return 'scatter';
  if (/distribution|spread|histogram/i.test(q)) return 'histogram';
  return 'clarify-question';
}
const cases = [
  ['Revenue over months?', 'line'],
  ['Which category leads?', 'sorted-bars'],
  ['Revenue mix?', 'stacked-bars'],
  ['Price versus rating?', 'scatter'],
  ['Hours spread?', 'histogram'],
  ['Make it pop?', 'clarify-question'],
];
let pass = 0;
for (const [q, expected] of cases) {
  const got = chartFor(q);
  if (got === expected) pass++;
  else console.log('MISS ' + q + ' -> ' + got);
}
console.log(pass + '/' + cases.length + ' questions routed');

